import torch
from semilearn.core.utils import get_net_builder
from torchvision import transforms
from PIL import Image
import os
from pathlib import Path
import shutil
import random

def load_model_for_inference(model_path, num_classes=4364):
    """
    加载训练好的模型用于推理
    """
    # 1. 加载 checkpoint
    print(f"Loading model from {model_path}")
    checkpoint = torch.load(model_path, map_location='cpu')

    # 2. 创建网络结构
    net_builder = get_net_builder('CBCNet', from_name=False)
    model = net_builder(num_classes=num_classes, pretrained=False)

    # 3. 加载模型参数
    # 注意：保存的是 EMA 模型，通常性能更好
    if 'ema_model' in checkpoint:
        print("Loading EMA model weights...")
        state_dict = checkpoint['ema_model']
    else:
        print("Loading regular model weights...")
        state_dict = checkpoint['model']

    # 4. 去除 'module.' 前缀（分布式训练遗留）
    new_state_dict = {}
    for k, v in state_dict.items():
        if k.startswith('module.'):
            new_key = k[7:]  # 去掉 'module.'
        else:
            new_key = k
        new_state_dict[new_key] = v

    # 5. 加载处理后的参数
    model.load_state_dict(new_state_dict)

    # 6. 设置为评估模式
    model.eval()

    # 7. 移动到 GPU（如果有）
    device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
    model = model.to(device)

    print(f"Model loaded successfully!")
    print(f"Best eval accuracy: {checkpoint.get('best_eval_acc', 'N/A')}")
    print(f"Trained iterations: {checkpoint.get('best_it', 'N/A')}")

    return model, device


def predict_image(model, image_path, device, img_size=32):
    """
    对单张图片进行预测
    """
    # 数据预处理（需要根据训练时的配置调整）
    transform = transforms.Compose([
        transforms.Resize((img_size, img_size)),
        transforms.ToTensor(),
        transforms.Normalize(mean=[0.485, 0.456, 0.406],  # ImageNet 标准化
                             std=[0.229, 0.224, 0.225])
    ])

    # 加载图片
    image = Image.open(image_path).convert('RGB')
    input_tensor = transform(image).unsqueeze(0).to(device)

    # 推理
    with torch.no_grad():
        output = model(input_tensor)
        probabilities = torch.softmax(output['logits'], dim=-1)
        predicted_class = torch.argmax(probabilities, dim=-1).item()
        confidence = probabilities[0, predicted_class].item()

    return predicted_class, confidence, probabilities


